B.agv=new A.cA("The best charity is that given when you are healthy and holding back, fearing poverty.","Abu Hurayrah (RA)","Sahih al-Bukhari 1419",null,null)
B.agr=new A.cA("Whoever does not show mercy will not be shown mercy.","Jarir ibn Abdullah (RA)","Sahih al-Bukhari 6013",null,null)
